#!/usr/bin/env python3
"""Offline DNS model-based regression workbench.

Reads one UTF-8 JSON document on stdin and writes one JSON document on stdout.

The document describes synthetic authoritative zones, resolver profiles,
candidate queries and observations.  The program builds a deterministic local
resolution model, adjudicates the observations against that model and selects
an exact minimum-cost diagnostic basis.
"""

import ipaddress
import json
import re
import sys
from array import array

# ---------------------------------------------------------------- constants

INPUT_LIMIT = 8 * 1024 * 1024
MAX_DEPTH = 32

MAX_ZONES = 16
MAX_TOTAL_RECORDS = 1024
MAX_RRSET = 64
MAX_PROFILES = 8
MAX_MAX_ALIASES = 64
MAX_QUERIES = 20
MAX_COST = 1000
MIN_COST = 1
MAX_OBSERVATIONS = 64
MAX_ANSWER_RECORDS = 128
MAX_TXT = 256
MAX_LABEL = 63
MAX_WIRE = 255
MAX_ID = 32

TYPES = ('A', 'AAAA', 'TXT', 'CNAME')
RCODES = ('NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED')
WILDCARDS = ('rfc', 'off', 'one-label')
CNAME_MODES = ('follow', 'stop')

ID_RE = re.compile(r'[A-Za-z0-9_-]{1,32}')
LABEL_RE = re.compile(r'[A-Za-z0-9_-]{1,63}')
OCTET_RE = re.compile(r'0|[1-9][0-9]{0,2}')
NAME_CHARS = frozenset('abcdefghijklmnopqrstuvwxyz'
                       'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-')


class Invalid(Exception):
    """Raised for every rejected input."""


def fail():
    raise Invalid()


# ---------------------------------------------------------------- json input

def _pairs_hook(pairs):
    seen = set()
    for key, _value in pairs:
        if key in seen:
            fail()
        seen.add(key)
    return dict(pairs)


def _reject_constant(_name):
    fail()


def _depth_ok(node, limit=MAX_DEPTH):
    stack = [(node, 1)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, dict):
            if depth > limit:
                return False
            for value in item.values():
                stack.append((value, depth + 1))
        elif isinstance(item, list):
            if depth > limit:
                return False
            for value in item:
                stack.append((value, depth + 1))
    return True


def parse_document(raw):
    if not isinstance(raw, (bytes, bytearray)):
        fail()
    if len(raw) > INPUT_LIMIT:
        fail()
    try:
        text = bytes(raw).decode('utf-8')
    except UnicodeDecodeError:
        fail()
    try:
        doc = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_reject_constant)
    except Invalid:
        raise
    except (ValueError, RecursionError):
        fail()
    if not _depth_ok(doc):
        fail()
    return doc


# ---------------------------------------------------------------- primitives

def require_keys(obj, keys):
    if not isinstance(obj, dict):
        fail()
    if set(obj.keys()) != set(keys):
        fail()


def canon_name(value):

def canon_name(value):
    """Validate and canonicalise an absolute domain name."""
    if type(value) is not str:
        fail()
    if value == '.':
        return '.'
    if not value.endswith('.'):
        fail()
    body = value[:-1]
    if body == '':
        fail()
    labels = body.split('.')
    wire = 1
    for label in labels:
        if label == '*':
            wire += 2
        elif LABEL_RE.fullmatch(label):
            wire += 1 + len(label)
        else:
            fail()
    if wire > MAX_WIRE:
        fail()
    return '.'.join(label.lower() for label in labels) + '.'


def canon_data(rtype, value):
    """Validate and canonicalise record data for the given type."""
    if type(value) is not str:
        fail()
    if rtype == 'A':
        parts = value.split('.')
        if len(parts) != 4:
            fail()
        for part in parts:
            if not OCTET_RE.fullmatch(part):
                fail()
            if int(part) > 255:
                fail()
        return value
    if rtype == 'AAAA':
        if '%' in value:
            fail()
        try:
            addr = ipaddress.IPv6Address(value)
        except ValueError:
            fail()
        return addr.compressed
    if rtype == 'TXT':
        if len(value) > MAX_TXT:
            fail()
        for char in value:
            code = ord(char)
            if code < 0x20 or code > 0x7E:
                fail()
        return value
    # CNAME
    return canon_name(value)


def canon_record(record):
    require_keys(record, ('owner', 'type', 'data'))
    rtype = record['type']
    if type(rtype) is not str or rtype not in TYPES:
        fail()
    owner = canon_name(record['owner'])
    data = canon_data(rtype, record['data'])
    return (owner, rtype, data)


def label_count(name):
    if name == '.':
        return 0
    return name.count('.')


def labels_of(name):
    if name == '.':
        return []
    return name[:-1].split('.')


def name_of_labels(labels):
    if not labels:
        return '.'
    return '.'.join(labels) + '.'


def parent_name(name):
    if name == '.':
        return '.'
    index = name.find('.')
    if index < 0:
        return '.'
    rest = name[index + 1:]
    return rest if rest else '.'


def at_or_below(name, origin):
    """True when name is the origin itself or a descendant of it."""
    if origin == '.':
        return True
    if name == origin:
        return True
    return name.endswith('.' + origin)


# ---------------------------------------------------------------- structures

def parse_zones(raw_zones):
    if not isinstance(raw_zones, list):
        fail()
    if len(raw_zones) > MAX_ZONES:
        fail()
    zones = []
    origins = set()
    total = 0
    for raw_zone in raw_zones:
        require_keys(raw_zone, ('origin', 'records'))
        origin = canon_name(raw_zone['origin'])
        if origin in origins:
            fail()
        origins.add(origin)
        raw_records = raw_zone['records']
        if not isinstance(raw_records, list):
            fail()
        total += len(raw_records)
        if total > MAX_TOTAL_RECORDS:
            fail()
        records = []
        for raw_record in raw_records:
            records.append(canon_record(raw_record))
        by_owner = {}
        for owner, rtype, data in records:
            if not at_or_below(owner, origin):
                fail()
            by_owner.setdefault(owner, {}).setdefault(rtype, set()).add(data)
        for owner, types in by_owner.items():
            for datas in types.values():
                if len(datas) > MAX_RRSET:
                    fail()
            if 'CNAME' in types:
                if len(types['CNAME']) != 1:
                    fail()
                if len(types) != 1:
                    fail()
                if owner == origin:
                    fail()
        existing = set()
        existing.add(origin)
        record_map = {}
        for owner, types in by_owner.items():
            existing.add(owner)
            cursor = owner
            while cursor != origin:
                cursor = parent_name(cursor)
                existing.add(cursor)
            for rtype, datas in types.items():
                record_map.setdefault(owner, {})[rtype] = sorted(datas)
        zones.append({'origin': origin, 'records': record_map, 'existing': existing})
    return zones


def parse_profiles(raw_profiles):
    if not isinstance(raw_profiles, list):
        fail()
    if len(raw_profiles) < 1 or len(raw_profiles) > MAX_PROFILES:
        fail()
    profiles = []
    seen = set()
    for raw_profile in raw_profiles:
        require_keys(raw_profile, ('id', 'max_aliases', 'cname', 'wildcard'))
        pid = raw_profile['id']
        if type(pid) is not str or not ID_RE.fullmatch(pid):
            fail()
        if pid in seen:
            fail()
        seen.add(pid)
        max_aliases = raw_profile['max_aliases']
        if type(max_aliases) is not int or max_aliases < 0 or max_aliases > MAX_MAX_ALIASES:
            fail()
        cname = raw_profile['cname']
        if type(cname) is not str or cname not in CNAME_MODES:
            fail()
        wildcard = raw_profile['wildcard']
        if type(wildcard) is not str or wildcard not in WILDCARDS:
            fail()
        profiles.append({'id': pid, 'max_aliases': max_aliases,
                         'cname': cname, 'wildcard': wildcard})
    return profiles


def parse_queries(raw_queries):
    if not isinstance(raw_queries, list):
        fail()
    if len(raw_queries) > MAX_QUERIES:
        fail()
    queries = []
    seen = set()
    for raw_query in raw_queries:
        require_keys(raw_query, ('id', 'name', 'type', 'cost'))
        qid = raw_query['id']
        if type(qid) is not str or not ID_RE.fullmatch(qid):
            fail()
        if qid in seen:
            fail()
        seen.add(qid)
        name = canon_name(raw_query['name'])
        qtype = raw_query['type']
        if type(qtype) is not str or qtype not in TYPES:
            fail()
        cost = raw_query['cost']

