"""Independent (deliberately different style) implementation of the model,
written straight from the instruction text, used to cross-check main.py."""

def canon_name(s):
    if s == '.':
        return '.'
    assert s.endswith('.')
    labs = s[:-1].split('.')
    return '.'.join(l.lower() for l in labs) + '.'

def anc(name):
    """All ancestors of name, longest first, ending with root."""
    out = []
    cur = name
    while True:
        out.append(cur)
        if cur == '.':
            break
        cur = '.'.join(cur.split('.')[1:]) + '.' if len(cur.split('.')) > 1 else '.'
    return out

def build(zones):
    out = []
    for z in zones:
        origin = canon_name(z['origin'])
        recs = {}
        exists = {origin}
        for r in z['records']:
            o = canon_name(r['owner']); t = r['type']
            if t == 'CNAME':
                d = canon_name(r['data'])
            elif t == 'AAAA':
                import ipaddress
                d = ipaddress.IPv6Address(r['data']).compressed
            else:
                d = r['data']
            recs.setdefault(o, {}).setdefault(t, set()).add(d)
            for a in anc(o):
                exists.add(a)
        # only ancestors down to the origin count
        exists = set()
        exists.add(origin)
        for o in recs:
            cur = o
            exists.add(cur)
            while cur != origin:
                cur = '.'.join(cur.split('.')[1:]) + '.' if len(cur.split('.')) > 1 else '.'
                exists.add(cur)
        out.append({'origin': origin, 'recs': recs, 'exists': exists})
    return out

def run(qname, qtype, prof, zones):
    wild = prof['wildcard']; cmode = prof['cname']; ma = prof['max_aliases']
    cur = canon_name(qname)
    seen = []
    ans = []
    foll = 0
    while True:
        seen.append(cur)
        if cur in seen[:-1]:
            return ('SERVFAIL','LOOP',cur,ans,seen)
        # most specific zone
        cand = [z for z in zones if z['origin']=='.' or cur==z['origin'] or cur.endswith('.'+z['origin'])]
        if not cand:
            return ('REFUSED','OUTSIDE',cur,ans,seen) if foll==0 else ('NOERROR','EXTERNAL',cur,ans,seen)
        z = max(cand, key=lambda z: len(z['origin'].split('.') if z['origin']!='.' else []))
        # source
        if cur in z['exists']:
            src = cur
        else:
            src = None
            if wild != 'off':
                enc = None
                for a in anc(cur)[1:]:
                    if a in z['exists']:
                        enc = a; break
                if enc is not None:
                    if not (wild == 'one-label' and len(anc(cur)) != len(anc(enc))):
                        cand_w = '*.' + enc if enc != '.' else '*.'
                        if cand_w in z['exists']:
                            src = cand_w
        if src is None:
            return ('NXDOMAIN','NXDOMAIN',cur,ans,seen)
        rr = z['recs'].get(src, {})
        cn = sorted(rr.get('CNAME', []))
        if qtype == 'CNAME':
            if cn:
                ans.append({'owner':cur,'type':'CNAME','data':cn[0]})
                return ('NOERROR','ANSWER',cur,ans,seen)
            return ('NOERROR','NODATA',cur,ans,seen)
        if cn:
            if cmode == 'stop':
                ans.append({'owner':cur,'type':'CNAME','data':cn[0]})
                return ('NOERROR','CNAME_STOP',cur,ans,seen)
            if foll >= ma:
                return ('SERVFAIL','LIMIT',cur,ans,seen)
            ans.append({'owner':cur,'type':'CNAME','data':cn[0]})
            foll += 1
            cur = cn[0]
            continue
        rrset = sorted(rr.get(qtype, []))
        if rrset:
            for d in rrset:
                ans.append({'owner':cur,'type':qtype,'data':d})
            return ('NOERROR','ANSWER',cur,ans,seen)
        return ('NOERROR','NODATA',cur,ans,seen)
