        if type(oid) is not str or not ID_RE.fullmatch(oid):
            fail()
        if oid in seen:
            fail()
        seen.add(oid)
        qid = raw_obs['query']
        pid = raw_obs['profile']
        if type(qid) is not str or qid not in query_ids:
            fail()
        if type(pid) is not str or pid not in profile_ids:
            fail()
        result = raw_obs['result']
        if not isinstance(result, dict):
            fail()
        status = result.get('status')
        if status == 'timeout':
            require_keys(result, ('status',))
            parsed = {'status': 'timeout'}
        elif status == 'response':
            require_keys(result, ('status', 'rcode', 'answer'))
            rcode = result['rcode']
            if type(rcode) is not str or rcode not in RCODES:
                fail()
            raw_answer = result['answer']
            if not isinstance(raw_answer, list):
                fail()
            if len(raw_answer) > MAX_ANSWER_RECORDS:
                fail()
            answer = []
            for raw_record in raw_answer:
                answer.append(canon_record(raw_record))
            parsed = {'status': 'response', 'rcode': rcode, 'answer': answer}
        else:
            fail()
        observations.append({'id': oid, 'query': qid, 'profile': pid,
                              'result': parsed})
    return observations


# ---------------------------------------------------------------- model

def select_zone(name, zones):
    best = None
    best_depth = -1
    for zone in zones:
        if at_or_below(name, zone['origin']):
            depth = label_count(zone['origin'])
            if depth > best_depth:
                best_depth = depth
                best = zone
    return best


def select_source(current, zone, wildcard_mode):
    """Return the record source name for current inside zone, or None."""
    existing = zone['existing']
    if current in existing:
        return current
    if wildcard_mode == 'off':
        return None
    # closest encloser: longest existing ancestor of current
    encloser = None
    cursor = parent_name(current)
    while True:
        if cursor in existing:
            encloser = cursor
            break
        if cursor == zone['origin']:
            break
        cursor = parent_name(cursor)
    if encloser is None:
        return None
    if wildcard_mode == 'one-label':
        if label_count(current) != label_count(encloser) + 1:
            return None
    wildcard = name_of_labels(['*'] + labels_of(encloser))
    if wildcard in existing:
        return wildcard
    return None


def resolve(qname, qtype, profile, zones):
    """Execute the frozen local resolution model."""
    wildcard_mode = profile['wildcard']
    cname_mode = profile['cname']
    max_aliases = profile['max_aliases']
    seen = set()
    trace = []
    answer = []
    current = qname
    followed = 0
    while True:
        trace.append(current)
        if current in seen:
            return ('SERVFAIL', 'LOOP', current, answer, trace)
        seen.add(current)
        zone = select_zone(current, zones)
        if zone is None:
            if followed == 0:
                return ('REFUSED', 'OUTSIDE', current, answer, trace)
            return ('NOERROR', 'EXTERNAL', current, answer, trace)
        source = select_source(current, zone, wildcard_mode)
        if source is None:
            return ('NXDOMAIN', 'NXDOMAIN', current, answer, trace)
        types = zone['records'].get(source, {})
        cnames = types.get('CNAME')
        if qtype == 'CNAME':
            if cnames:
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': cnames[0]})
                return ('NOERROR', 'ANSWER', current, answer, trace)
            return ('NOERROR', 'NODATA', current, answer, trace)
        if cnames:
            if cname_mode == 'stop':
                answer.append({'owner': current, 'type': 'CNAME',
                               'data': cnames[0]})
                return ('NOERROR', 'CNAME_STOP', current, answer, trace)
            if followed >= max_aliases:
                return ('SERVFAIL', 'LIMIT', current, answer, trace)
            answer.append({'owner': current, 'type': 'CNAME',
                           'data': cnames[0]})
            followed += 1
            current = cnames[0]
            continue

        if rrset:
            for data in rrset:
                answer.append({'owner': current, 'type': qtype, 'data': data})
            return ('NOERROR', 'ANSWER', current, answer, trace)
        return ('NOERROR', 'NODATA', current, answer, trace)


# ---------------------------------------------------------------- analysis

def compute_runs(queries, profiles, zones):
    runs = []
    projections = {}
    for query in sorted(queries, key=lambda item: item['id']):
        for profile in sorted(profiles, key=lambda item: item['id']):
            rcode, termination, final_name, answer, trace = resolve(
                query['name'], query['type'], profile, zones)
            runs.append({
                'query': query['id'],
                'profile': profile['id'],
                'rcode': rcode,
                'termination': termination,
                'final_name': final_name,
                'answer': answer,
                'trace': trace,
            })
            projections[(query['id'], profile['id'])] = (
                rcode,
                frozenset((item['owner'], item['type'], item['data'])
                          for item in answer),
            )
    return runs, projections


def compute_audits(observations, projections):
    audits = []
    for observation in sorted(observations, key=lambda item: item['id']):
        result = observation['result']
        if result['status'] == 'timeout':
            audits.append({'id': observation['id'], 'verdict': 'unobserved',
                           'different': []})
            continue
        observed_rcode = result['rcode']
        observed = frozenset(result['answer'])
        run_rcode, run_answer = projections[(observation['query'],
                                            observation['profile'])]
        different = []
        if observed_rcode != run_rcode:
            different.append('rcode')
        if observed != run_answer:
            different.append('answer')
        audits.append({
            'id': observation['id'],
            'verdict': 'match' if not different else 'divergence',
            'different': different,
        })
    return audits


def _pack_bound(order, conflict, min_cost, covered, pair_count):
    """Admissible lower bound on the additional cost still required."""
    total = 0
    picked = 0
    for element in order:
        if (covered >> element) & 1:
            continue
        if (conflict[element] & picked) == 0:
            picked |= 1 << element
            total += min_cost[element]
    return total


def _greedy_cover(items, full, pair_count):
    """Cheap greedy cover used as an initial upper bound."""
    covered = 0
    chosen = []
    cost = 0
    while covered != full:
        best = None
        for index, (mask, item_cost, _qid) in enumerate(items):
            gain = bin(mask & ~covered).count('1')
            if gain == 0:
                continue
            key = (-gain, item_cost, index)
            if best is None or key < best[0]:
                best = (key, index)
        if best is None:
            return None
        index = best[1]
        covered |= items[index][0]
        cost += items[index][1]
        chosen.append(items[index][2])

