def _exhaustive_cover(items, full):
    """Exact fallback: enumerate every subset of the candidate queries."""
    count = len(items)
    size = 1 << count
    unions = array('I', bytes(4 * size))
    costs = array('H', bytes(2 * size))
    best_cost = None
    best_count = None
    best_mask = 0
    for mask in range(size):
        if mask:
            low = mask & -mask
            index = low.bit_length() - 1
            previous = mask ^ low
            union = unions[previous] | items[index][0]
            unions[mask] = union
            value = costs[previous] + items[index][1]
            costs[mask] = value
        else:
            union = 0
            value = 0
        if union == full:
            length = mask.bit_count()
            if best_cost is None or (value, length) < (best_cost, best_count):
                best_cost = value
                best_count = length
                best_mask = mask
    chosen = [items[index][2] for index in range(count)
              if (best_mask >> index) & 1]
    return best_cost, best_count, chosen


def _solve_cover(items, full, pair_count):
    """Exact minimum cost (then minimum count) set cover."""
    if not items:
        return None
